module MediaCoverage(\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] sectors [0:15],\n    input [3:0] K_in,\n    input [3:0] C_in,\n    output reg [3:0] result,\n    output reg done\n);\n\n    // State definitions\n    localparam [2:0] IDLE    = 3'd0;\n    localparam [2:0] INIT    = 3'd1;\n    localparam [2:0] SCAN    = 3'd2;\n    localparam [2:0] CHECK   = 3'd3;\n    localparam [2:0] UPDATE  = 3'd4;\n    localparam [2:0] DONE    = 3'd5;\n    \n    reg [2:0] state, next_state;\n    \n    // Internal registers\n    reg [3:0] K, C;\n    reg [15:0] used_mask;           // Bitmask of used sectors\n    reg [3:0] company_count;        // Number of companies found\n    reg [3:0] start_idx;            // Current starting sector index\n    reg [3:0] end_idx;              // Current end sector index\n    reg [15:0] color_mask;          // Bitmask of colors in current range\n    reg [3:0] distinct_colors;      // Count of distinct colors\n    reg [3:0] range_len;            // Current range length\n    reg [3:0] temp_idx;             // Temporary index for iteration\n    reg [7:0] cycle_counter;        // Prevent infinite loops\n    localparam [7:0] MAX_CYCLES = 8'd200;\n    \n    // Helper to double sectors array for wrap-around simulation\n    // We'll handle wrap-around manually during scan\n    \n    // Distinct color count helper function (combinational logic)\n    // This is implemented as a separate always block for clarity\n    reg [15:0] temp_color_mask;\n    reg [3:0] temp_distinct_count;\n    reg [3:0] check_idx;\n    \n    always @(*) begin\n        temp_color_mask = 16'd0;\n        temp_distinct_count = 4'd0;\n        for (check_idx = 4'd0; check_idx < 4'd16; check_idx = check_idx + 4'd1) begin\n            if (check_idx < range_len) begin\n                // Get actual index in circular array\n                temp_idx = start_idx + check_idx;\n                if (temp_idx >= 4'd16) begin\n                    temp_idx = temp_idx - 4'd16;\n                end\n                // Set bit for this color (colors are 1-16, so bit index = color-1)\n                temp_color_mask[sectors[temp_idx] - 1'b1] = 1'b1;\n            end\n        end\n        // Count bits in mask\n        temp_distinct_count = 4'd0;\n        for (int i = 0; i < 16; i = i + 1) begin\n            if (temp_color_mask[i]) begin\n                temp_distinct_count = temp_distinct_count + 4'd1;\n            end\n        end\n    end\n    \n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 4'd0;\n            done <= 1'b0;\n            K <= 4'd0;\n            C <= 4'd0;\n            used_mask <= 16'd0;\n            company_count <= 4'd0;\n            start_idx <= 4'd0;\n            end_idx <= 4'd0;\n            color_mask <= 16'd0;\n            distinct_colors <= 4'd0;\n            range_len <= 4'd0;\n            temp_idx <= 4'd0;\n            cycle_counter <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    result <= 4'd0;\n                    if (start) begin\n                        state <= INIT;\n                    end\n                end\n                \n                INIT: begin\n                    // Initialize variables for new calculation\n                    K <= K_in;\n                    C <= C_in;\n                    used_mask <= 16'd0;\n                    company_count <= 4'd0;\n                    start_idx <= 4'd0;\n                    cycle_counter <= 8'd0;\n                    state <= SCAN;\n                end\n                \n                SCAN: begin\n                    // Find next unused sector as start index\n                    if (start_idx < 4'd16) begin\n                        if (!used_mask[start_idx]) begin\n                            // Found starting position\n                            range_len <= K;\n                            state <= CHECK;\n                        end else begin\n                            start_idx <= start_idx + 4'd1;\n                        end\n                    end else begin\n                        // All sectors processed or no valid start found\n                        state <= DONE;\n                    end\n                end\n                \n                CHECK: begin\n                    // Check if current range is valid\n                    // Check if any sector in range is already used\n                    reg range_conflict;\n                    range_conflict = 1'b0;\n                    for (int i = 0; i < 16; i = i + 1) begin\n                        if (i < range_len) begin\n                            temp_idx = start_idx + i[3:0];\n                            if (temp_idx >= 4'd16) temp_idx = temp_idx - 4'd16;\n                            if (used_mask[temp_idx]) range_conflict = 1'b1;\n                        end\n                    end\n                    \n                    if (range_conflict || (range_len > 4'd16)) begin\n                        // Invalid range - try longer range\n                        if (range_len < 4'd16) begin\n                            range_len <= range_len + 4'd1;\n                            state <= CHECK;\n                        end else begin\n                            // No valid range from this start\n                            start_idx <= start_idx + 4'd1;\n                            state <= SCAN;\n                        end\n                    end else begin\n                        // Check distinct colors\n                        distinct_colors <= temp_distinct_count;\n                        color_mask <= temp_color_mask;\n                        state <= UPDATE;\n                    end\n                    cycle_counter <= cycle_counter + 8'd1;\n                end\n                \n                UPDATE: begin\n                    // Update if valid\n                    if (distinct_colors >= C) begin\n                        // Valid range found\n                        company_count <= company_count + 4'd1;\n                        // Mark sectors as used\n                        for (int i = 0; i < 16; i = i + 1) begin\n                            if (i < range_len) begin\n                                temp_idx = start_idx + i[3:0];\n                                if (temp_idx >= 4'd16) temp_idx = temp_idx - 4'd16;\n                                used_mask[temp_idx] <= 1'b1;\n                            end\n                        end\n                        // Move to next sector after this range\n                        start_idx <= start_idx + range_len;\n                        if (start_idx + range_len >= 4'd16) begin\n                            start_idx <= 4'd16;\n                        end\n                    end else begin\n                        // Not valid, try longer range\n                        if (range_len < 4'd16) begin\n                            range_len <= range_len + 4'd1;\n                            state <= CHECK;\n                        end else begin\n                            start_idx <= start_idx + 4'd1;\n                        end\n                    end\n                    if (range_len >= 4'd16 || (start_idx + range_len >= 4'd16 && range_len >= K)) begin\n                        state <= SCAN;\n                    end else if (range_len < 4'd16) begin\n                        state <= CHECK;\n                    end else begin\n                        state <= SCAN;\n                    end\n                    cycle_counter <= cycle_counter + 8'd1;\n                end\n                \n                DONE: begin\n                    result <= company_count;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: begin\n                    state <= IDLE;\n                end\n            endcase\n            \n            // Safety timeout\n            if (cycle_counter >= MAX_CYCLES && state != IDLE && state != DONE) begin\n                state <= DONE;\n            end\n        end\n    end\nendmodule